package com.example.starter.signing.web;

import java.time.Instant;
import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;

/**
 * 建包请求：当前文档摘要、UTC 到期时间与有序签署步骤。
 *
 * @param documentHash 当前修订（修订号 1）文档 SHA-256 十六进制摘要
 * @param expiresAt    UTC 到期时间
 * @param steps        有序步骤；同一步骤的 signers 为并行签署人，全部完成才开放下一步
 */
public record CreatePackageRequest(
        @NotBlank @Pattern(regexp = "[0-9a-fA-F]{64}") String documentHash,
        @NotNull Instant expiresAt,
        @NotEmpty @Valid List<StepSpec> steps) {

    /**
     * 单个签署步骤定义。
     *
     * @param stepOrder 步骤序号，从 1 开始且必须连续
     * @param signers   并行签署人列表，同一步骤内不得重复
     */
    public record StepSpec(
            @NotNull Integer stepOrder,
            @NotEmpty List<@NotBlank String> signers) {
    }
}

package com.example.starter.signing.web;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;

/**
 * 签名提交请求。
 *
 * @param requestId      幂等请求键；同键同完整参数返回首次结果，同键异参返回 409
 * @param signer         签署人标识
 * @param revision       提交方针对的文档修订号，必须等于签署包当前修订号
 * @param documentHash   提交方计算的文档 SHA-256 摘要，必须与当前修订摘要一致
 * @param expectedVersion 期望版本（当前修订号），与 revision 一同用于乐观并发校验
 * @param signature       合成签名值，由本地验证适配器校验
 */
public record SignatureSubmitRequest(
        @NotBlank String requestId,
        @NotBlank String signer,
        @NotNull Integer revision,
        @NotBlank @Pattern(regexp = "[0-9a-fA-F]{64}") String documentHash,
        @NotNull Integer expectedVersion,
        @NotBlank String signature) {
}

package com.example.starter.signing.web;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;

/**
 * 文档修订请求：仅在最终完成前允许，会使旧修订签名全部失效并重置到第一步。
 *
 * @param newDocumentHash 新修订文档 SHA-256 十六进制摘要
 */
public record RevisionRequest(
        @NotBlank @Pattern(regexp = "[0-9a-fA-F]{64}") String newDocumentHash) {
}

package com.example.starter.signing.web;

/**
 * 取消请求；原因为可选合成信息。
 *
 * @param reason 取消原因，可为空
 */
public record CancelRequest(String reason) {
}

