        } catch (EmptyResultDataAccessException e) {
            return null;
        }
    }

    public Optional<SigningPackage> findPackage(String packageId) {
        try {
            return Optional.ofNullable(jdbc.queryForObject(
                    "SELECT * FROM signing_package WHERE id = ?",
