                "FLOW_COMPLETED", "流程已完成冻结，迟到签名被拒绝");
    }
    if (pkg.getStatus() == PackageStatus.EXPIRED) {
        return rejected(packageId, request, fingerprint, now, HttpStatus.GONE,
                "PACKAGE_EXPIRED", "流程已过期，签名被拒绝");
    }
